const ANSWERED=[
{d:"2026-08-18",seg:"دوو خولەک، یەک پرسیار",segEn:"Two Minutes, One Question",
 ku:{q:"باوکم کۆرتیزۆنی بۆ ئێشی جومگە دەخوات و ئێستا شەکرەکەی بەرز بووە. پەیوەندییان هەیە؟",
     a:"بەڵێ. کۆرتیزۆن شەکری خوێن بەرز دەکاتەوە، بەتایبەت لە بەکارهێنانی درێژخایەندا. ئەمە واتای ئەوە نییە کە یەکسەر ڕایبگرێت — ڕاگرتنی لەناکاو مەترسیدارە. پێویستە پزیشکەکەی ئاگادار بکرێتەوە."},
 en:{q:"My father takes cortisone for joint pain and now his sugar has risen. Are they connected?",
     a:"Yes. Cortisone raises blood sugar, particularly with long-term use. This does not mean stopping it immediately — stopping suddenly is dangerous. His doctor needs to be told."}},
{d:"2026-08-11",seg:"ڕاست یان هەڵە",segEn:"True or False?",
 ku:{q:"لە فەیسبووک دەڵێن ئاوی لیمۆی گەرم بە بەتاڵی گەدە چەوری دەتوێنێتەوە. ڕاستە؟",
     a:"نەخێر. هیچ خواردنەوەیەک چەوری ناتوێنێتەوە. ئاوی لیمۆ زیانی نییە، بەڵام ئەو بانگەشەیە بنەمای زانستی نییە."},
 en:{q:"On Facebook they say warm lemon water on an empty stomach dissolves fat. Is it true?",
     a:"No. No drink dissolves fat. Lemon water is harmless, but the claim has no scientific basis."}},
{d:"2026-08-04",seg:"کۆنتەری دەرمانخانە",segEn:"The Pharmacy Counter",
 ku:{q:"منداڵەکەم ٤ ساڵە و شەربەتی کۆکەی پێدەدەم هەموو شەوێک. ئاسایییە؟",
     a:"بۆ منداڵی کەمتر لە ٦ ساڵ پێشنیار ناکرێت بەبێ ڕاوێژی پزیشک. زۆرێک لەم شەربەتانە پاراسیتامۆلیان تێدایە، بۆیە لەوانەیە بەبێ ئەوەی بزانیت دوو جار وەریبگرێت."},
 en:{q:"My child is 4 and I give cough syrup every night. Is that all right?",
     a:"Not recommended under 6 without a doctor's advice. Many of these syrups contain paracetamol, so the child may be getting a double dose without you realising."}},
{d:"2026-07-28",seg:"دوو خولەک، یەک پرسیار",segEn:"Two Minutes, One Question",
 ku:{q:"پزیشک وتی پەستانی خوێنم بەرزە بەڵام هیچ هەست ناکەم. پێویستە دەرمان بخۆم؟",
     a:"بەڵێ. پەستانی خوێنی بەرز زۆرجار هیچ نیشانەیەکی نییە — زیانەکەی بێدەنگە و بە ساڵان کۆدەبێتەوە. هەستنەکردن واتای باشبوون نییە."},
 en:{q:"The doctor says my blood pressure is high but I feel nothing. Do I need medication?",
     a:"Yes. High blood pressure usually causes no symptoms — the damage is silent and accumulates over years. Feeling well does not mean it is under control."}}];

